SELECT jsonb_build_object('category','identity','host',inet_server_addr(),'port',inet_server_port(),'database',current_database(),'user',current_user,'version',version(),'cluster',current_setting('cluster_name'),'transaction_read_only',current_setting('transaction_read_only'),'default_transaction_read_only',current_setting('default_transaction_read_only'),'statement_timeout',current_setting('statement_timeout'),'lock_timeout',current_setting('lock_timeout'),'superuser',(SELECT rolsuper FROM pg_roles WHERE rolname=current_user));
SELECT jsonb_build_object('category','session_activity','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT backend_type,state,count(*) AS sessions,count(*) FILTER(WHERE xact_start IS NOT NULL) AS open_transactions,count(*) FILTER(WHERE xact_start<clock_timestamp()-interval '30 seconds') AS transactions_over_30s,count(*) FILTER(WHERE wait_event_type='Lock') AS lock_waiters FROM pg_catalog.pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() GROUP BY backend_type,state ORDER BY backend_type,state LIMIT 30) x;
SELECT jsonb_build_object('category','locks','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT locktype,mode,granted,count(*) AS locks FROM pg_catalog.pg_locks WHERE database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND pid<>pg_backend_pid() GROUP BY locktype,mode,granted ORDER BY locktype,mode LIMIT 100) x;
SELECT jsonb_build_object('category','prepared_transactions','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT count(*) AS prepared_transactions FROM pg_catalog.pg_prepared_xacts WHERE database=current_database()) x;
SELECT jsonb_build_object('category','recovery_settings','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT name,CASE WHEN name='archive_command' THEN (setting<>'')::text ELSE setting END AS setting FROM pg_catalog.pg_settings WHERE name IN ('archive_mode','archive_command','wal_level','data_checksums') ORDER BY name LIMIT 10) x;
SELECT jsonb_build_object('category','archiver','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT archived_count,last_archived_time,failed_count,last_failed_time FROM pg_catalog.pg_stat_archiver LIMIT 1) x;
SELECT jsonb_build_object('category','ledger','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT migration_id,filename,content_sha256,transactional,runner_version,outcome FROM platform.schema_migrations ORDER BY migration_id LIMIT 100) x;
SELECT jsonb_build_object('category','relations','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT c.oid AS oid,n.nspname||'.'||c.relname AS name,c.relkind,pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity,c.relforcerowsecurity FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND c.relkind IN ('r','v','m','S','p') ORDER BY name LIMIT 1000) x;
SELECT jsonb_build_object('category','columns','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull,pg_get_expr(d.adbin,d.adrelid) AS default_expression FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped ORDER BY relation,a.attnum LIMIT 10000) x;
SELECT jsonb_build_object('category','constraints','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT k.oid AS oid,k.conrelid AS relation_oid,k.confrelid AS referenced_relation_oid,n.nspname||'.'||c.relname AS relation,k.conname AS name,k.contype,k.convalidated,pg_get_constraintdef(k.oid,true) AS definition FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class c ON c.oid=k.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' ORDER BY relation,name LIMIT 10000) x;
SELECT jsonb_build_object('category','indexes','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,i.relname AS name,x.indisvalid,x.indisready,pg_get_indexdef(i.oid) AS definition FROM pg_catalog.pg_index x JOIN pg_catalog.pg_class c ON c.oid=x.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_class i ON i.oid=x.indexrelid WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' ORDER BY relation,name LIMIT 10000) x;
SELECT jsonb_build_object('category','functions','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT p.oid AS oid,n.nspname||'.'||p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex') AS definition_sha256 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('knowledge','config','regulatory','controls','org','ops_audit','platform','iam','audit','risk','evidence','remediation','privacy') AND p.prokind='f' ORDER BY name,arguments LIMIT 1000) x;
SELECT jsonb_build_object('category','triggers','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,t.tgname AS name,t.tgenabled,pg_get_triggerdef(t.oid,true) AS definition FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname NOT IN ('pg_catalog','information_schema') ORDER BY relation,name LIMIT 2000) x;
SELECT jsonb_build_object('category','clock','utc',clock_timestamp(),'cluster_system_identifier',(SELECT system_identifier::text FROM pg_control_system()));
SELECT jsonb_build_object('category','data_fingerprint','relation','ai.ai_jobs','rows',count(*),'sha256',encode(sha256(convert_to(coalesce(string_agg(h,'' ORDER BY h COLLATE "C"),''),'UTF8')),'hex')) FROM (SELECT encode(sha256(convert_to((to_jsonb(t)-ARRAY[]::text[])::text,'UTF8')),'hex') h FROM ai.ai_jobs t LIMIT 100001) s;
